{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "label",
      "type": "string",
      "description": "Label text for the input (required for accessibility).",
      "required": true
    },
    {
      "name": "isLabelHidden",
      "type": "boolean",
      "description": "Visually hides the label while keeping it accessible to screen readers.",
      "default": "false"
    },
    {
      "name": "description",
      "type": "string",
      "description": "Description text displayed between the label and input."
    },
    {
      "name": "isOptional",
      "type": "boolean",
      "description": "Shows an \"(optional)\" indicator next to the label. Mutually exclusive with isRequired.",
      "default": "false"
    },
    {
      "name": "isRequired",
      "type": "boolean",
      "description": "Marks the field as required and sets aria-required. Mutually exclusive with isOptional.",
      "default": "false"
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Disables the input and suppresses interactions. The input stays focusable and exposes `aria-disabled`.",
      "default": "false"
    },
    {
      "name": "disabledMessage",
      "type": "string",
      "description": "Explains why the input is disabled. With isDisabled, shows a tooltip on hover/keyboard focus and describes the input (activation stays blocked). Use this instead of wrapping a disabled TimeInput in Tooltip."
    },
    {
      "name": "value",
      "type": "ISOTimeString",
      "description": "Controlled time value in ISO format (HH:MM or HH:MM:SS)."
    },
    {
      "name": "onChange",
      "type": "(value: ISOTimeString | undefined) => void",
      "description": "Callback fired when the time changes. Receives undefined when the input is cleared."
    },
    {
      "name": "changeAction",
      "type": "(value: ISOTimeString | undefined) => void | Promise<void>",
      "description": "Async action fired after onChange. Wrapped in a React transition to provide optimistic UI; triggers the loading spinner while pending."
    },
    {
      "name": "isLoading",
      "type": "boolean",
      "description": "Puts the input into a loading state, displaying a spinner.",
      "default": "false"
    },
    {
      "name": "min",
      "type": "ISOTimeString",
      "description": "Minimum selectable time in ISO format. Values outside the range are rejected."
    },
    {
      "name": "max",
      "type": "ISOTimeString",
      "description": "Maximum selectable time in ISO format. Values outside the range are rejected."
    },
    {
      "name": "hasSeconds",
      "type": "boolean",
      "description": "Includes seconds in the time display and parsing.",
      "default": "false"
    },
    {
      "name": "hasClear",
      "type": "boolean",
      "description": "Shows a clear button when a value is set and the input is not disabled.",
      "default": "false"
    },
    {
      "name": "hourFormat",
      "type": "'12h' | '24h'",
      "description": "Controls the display format. '12h' shows the locale's day period (e.g. '2:30 PM', '오후 2:30'); '24h' uses 24-hour notation (e.g. '14:30'). When unset, follows the InternationalizationProvider locale's hour cycle: en-US reads 12-hour, en-GB and de-DE read 24-hour. To honor a person's own preference, pass it on the locale tag (e.g. 'en-US-u-hc-h23') rather than per field.",
      "default": "the locale's hour cycle"
    },
    {
      "name": "increment",
      "type": "number",
      "description": "Number of minutes to add or subtract when the user presses the up or down arrow key. Steps are whole minutes; a fractional value leaves the time unchanged.",
      "default": "1"
    },
    {
      "name": "presentation",
      "type": "'text-input' | 'popover' | 'bottom-sheet' | 'native' | 'adaptive-bottom-sheet' | 'adaptive-native'",
      "description": "Which surface selects the time. 'adaptive-native' (the default) uses Astryx's typed field on a fine pointer and the browser/OS input type=time on a coarse pointer — except hasSeconds or increment other than 1, which retain the typed field because iOS has no seconds wheel and treats step as validation rather than picker cadence; 'native' always uses the browser/OS control with no Astryx fallback; 'adaptive-bottom-sheet' uses the typed field on a fine pointer and Astryx's bottom-sheet time wheels on a coarse pointer; 'bottom-sheet' forces the wheels on every pointer; 'text-input' (like 'popover', which has no distinct TimeInput surface) keeps only the typed field. Native mode forwards min/max and enforces them on commit. hourFormat formats the closed value; the open OS picker follows the device locale.",
      "default": "'adaptive-native'"
    },
    {
      "name": "nativePicker",
      "type": "'touch' | 'always' | 'never'",
      "description": "Deprecated: use presentation ('touch' = 'adaptive-native', 'always' = 'native', 'never' = 'text-input'). Still works exactly as released; presentation wins when both are set.",
      "default": "'touch'"
    },
    {
      "name": "placeholder",
      "type": "string",
      "description": "Placeholder text shown when no time is selected. When the input is focused and empty, a format hint overrides this text.",
      "default": "'Select a time'"
    },
    {
      "name": "size",
      "type": "'sm' | 'md' | 'lg'",
      "description": "Controls the height of the input element.",
      "default": "'md'"
    },
    {
      "name": "status",
      "type": "{type: 'warning' | 'error' | 'success', message?: string}",
      "description": "Status indicator that colors the border and displays an icon. When a message is provided it is rendered below the input."
    },
    {
      "name": "statusVariant",
      "type": "'attached' | 'detached' | 'tooltip'",
      "description": "How the status message is placed relative to the input. attached overlaps directly below the input (bordered treatment); detached floats below as a separate element with spacing; tooltip hides the message box and surfaces it in a tooltip on the status icon.",
      "default": "'attached'"
    },
    {
      "name": "labelTooltip",
      "type": "string",
      "description": "Tooltip text rendered as an info icon at the end of the label row."
    },
    {
      "name": "width",
      "type": "SizeValue",
      "description": "Width of the field (number = pixels, string used as-is, e.g. \"100%\"). Sizes the whole field (label, control, and status) so they stay aligned."
    },
    {
      "name": "containerXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the Field box around the label, control, and status. containerClassName and containerStyle take a class name and inline styles for the same box. No effect (development warning) where no Field box renders: inside InputGroup (style the group) and in a horizontal-labels FormLayout."
    },
    {
      "name": "controlXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the visual control box: the bordered element that holds the text, icons, and end controls, never the native input. controlClassName and controlStyle take a class name and inline styles for the same box. Replaces root xstyle, className, and style, which this component does not accept."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
